1	package zkcircuit
2	
3	import (
4		"fmt"
5		"os"
6	)
7	
8	// This file holds the constraint lifecycle operations: importing a draft
9	// definition from a JSON file, compiling a frozen version into a hashed
10	// artifact, and checking an input assignment against an artifact.
11	
12	// ImportConstraints reads a definition JSON file and stores it for one draft
13	// circuit version, replacing any previously imported definition as a whole.
14	//
15	// The version must exist and be a draft; a frozen version's definition can
16	// never be replaced (ErrFrozen). The file is parsed and fully validated
17	// against the version's declared counts before anything is committed, so a
18	// rejected import leaves the previous definition byte-for-byte in place.
19	// Unknown versions yield ErrNotFound; malformed or illegal definitions
20	// yield ErrInvalidArgument.
21	func (s *Store) ImportConstraints(name string, version int, path string) (Definition, error) {
22		if err := validateCircuitKey(name, version); err != nil {
23			return Definition{}, err
24		}
25		raw, err := os.ReadFile(path)
26		if err != nil {
27			return Definition{}, invalidf("cannot read constraint definition file %q: %v", path, err)
28		}
29	
30		var result Definition
31		err = s.withLock(func() (bool, error) {
32			circuit := findCircuit(s.data.Circuits, name, version)
33			if circuit == nil {
34				return false, notFoundf("circuit %q version %d does not exist", name, version)
35			}
36			if circuit.Frozen {
37				return false, frozenf("circuit %q version %d is frozen; its constraint definition cannot be replaced", name, version)
38			}
39			parsed, perr := parseDefinitionJSON(raw, circuit.PublicInputs, circuit.PrivateInputs, circuit.Constraints)
40			if perr != nil {
41				return false, perr
42			}
43			persisted := parsed.toPersist()
44			circuit.Definition = &persisted
45			result = parsed.toExport()
46			return true, nil
47		})
48		return result, err
49	}
50	
51	// GetDefinition returns the imported definition of one version. A version
52	// without one yields ErrDefinitionMissing, and an unknown version
53	// ErrNotFound.
54	func (s *Store) GetDefinition(name string, version int) (Definition, error) {
55		if err := validateCircuitKey(name, version); err != nil {
56			return Definition{}, err
57		}
58		var result Definition
59		err := s.withLockRead(func() error {
60			circuit := findCircuit(s.data.Circuits, name, version)
61			if circuit == nil {
62				return notFoundf("circuit %q version %d does not exist", name, version)
63			}
64			if circuit.Definition == nil {
65				return definitionMissingf("circuit %q version %d has no constraint definition", name, version)
66			}
67			parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
68			if perr != nil {
69				return corruptf("circuit %q v%d stored definition cannot be read: %v", name, version, perr)
70			}
71			result = parsed.toExport()
72			return nil
73		})
74		return result, err
75	}
76	
77	// CompileCircuit compiles a frozen circuit version into an artifact.
78	//
79	// Only frozen versions compile: unknown versions yield ErrNotFound, drafts
80	// ErrNotFrozen. A version whose counts were registered but which never had a
81	// definition imported yields ErrDefinitionMissing. Repeated compilation of
82	// the same version is idempotent and returns the identical artifact; other
83	// versions' artifacts are unaffected.
84	func (s *Store) CompileCircuit(name string, version int) (Artifact, error) {
85		if err := validateCircuitKey(name, version); err != nil {
86			return Artifact{}, err
87		}
88		var result Artifact
89		err := s.withLock(func() (bool, error) {
90			circuit := findCircuit(s.data.Circuits, name, version)
91			if circuit == nil {
92				return false, notFoundf("circuit %q version %d does not exist", name, version)
93			}
94			if !circuit.Frozen {
95				return false, notFrozenf("circuit %q version %d must be frozen before compilation", name, version)
96			}
97			if existing := findArtifact(s.data.Artifacts, name, version); existing != nil {
98				result = artifactFromPersist(*existing)
99				return false, nil
100			}
101			if circuit.Definition == nil {
102				return false, definitionMissingf("circuit %q version %d has only registered counts and no constraint definition; import one before freezing",
103					name, version)
104			}
105			parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
106			if perr != nil {
107				return false, corruptf("stored definition for %q v%d is unreadable: %v", name, version, perr)
108			}
109			if !parsed.compatibleWith(circuit.Constraints, circuit.PublicInputs, circuit.PrivateInputs) {
110				return false, corruptf("stored definition for %q v%d no longer matches its declared counts", name, version)
111			}
112			record := persistArtifact{
113				Name:        name,
114				Version:     version,
115				Modulus:     parsed.modulus,
116				Constraints: len(parsed.constraints),
117				Hash:        artifactHash(name, version, parsed),
118			}
119			s.data.Artifacts = append(s.data.Artifacts, record)
120			result = artifactFromPersist(record)
121			return true, nil
122		})
123		return result, err
124	}
125	
126	// GetArtifact returns the compiled artifact for one version. A version
127	// without one yields ErrArtifactMissing, and an unknown version ErrNotFound.
128	func (s *Store) GetArtifact(name string, version int) (Artifact, error) {
129		if err := validateCircuitKey(name, version); err != nil {
130			return Artifact{}, err
131		}
132		var result Artifact
133		err := s.withLockRead(func() error {
134			circuit := findCircuit(s.data.Circuits, name, version)
135			if circuit == nil {
136				return notFoundf("circuit %q version %d does not exist", name, version)
137			}
138			existing := findArtifact(s.data.Artifacts, name, version)
139			if existing == nil {
140				return artifactMissingf("circuit %q version %d has no compiled artifact", name, version)
141			}
142			result = artifactFromPersist(*existing)
143			return nil
144		})
145		return result, err
146	}
147	
148	// CheckInput tests one input assignment against the named version's
149	// compiled artifact. hash must equal that artifact's hash, binding the check
150	// to an explicit compilation result.
151	//
152	// Gating errors are reported distinctly: unknown version ErrNotFound,
153	// unfrozen version ErrNotFrozen, no compiled artifact ErrArtifactMissing and
154	// a hash that does not belong to the target version ErrArtifactMismatch. A
155	// malformed witness (missing arrays, wrong lengths or illegal values) yields
156	// ErrInvalidInput and never reaches evaluation.
157	//
158	// On success the verdict reports satisfaction, the bound artifact hash and,
159	// when unsatisfied, the 1-based index of the first failing constraint. No
160	// private input value is included in the result and no proof job is created.
161	func (s *Store) CheckInput(name string, version int, hash string, witness Witness) (CheckResult, error) {
162		if err := validateCircuitKey(name, version); err != nil {
163			return CheckResult{}, err
164		}
165		if hash == "" {
166			return CheckResult{}, invalidf("an artifact hash is required to check inputs")
167		}
168		var result CheckResult
169		err := s.withLockRead(func() error {
170			circuit := findCircuit(s.data.Circuits, name, version)
171			if circuit == nil {
172				return notFoundf("circuit %q version %d does not exist", name, version)
173			}
174			if !circuit.Frozen {
175				return notFrozenf("circuit %q version %d must be frozen before inputs can be checked", name, version)
176			}
177			artifact := findArtifact(s.data.Artifacts, name, version)
178			if artifact == nil {
179				return artifactMissingf("circuit %q version %d has no compiled artifact", name, version)
180			}
181			if artifact.Hash != hash {
182				return artifactMismatchf("artifact hash %q does not belong to circuit %q version %d (bound hash %q)",
183					hash, name, version, artifact.Hash)
184			}
185			if circuit.Definition == nil {
186				return corruptf("artifact for %q v%d exists but its definition is missing", name, version)
187			}
188			parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
189			if perr != nil {
190				return corruptf("stored definition for %q v%d is unreadable: %v", name, version, perr)
191			}
192			if err := validateWitness(witness, parsed.public, parsed.private); err != nil {
193				return err
194			}
195			failure := parsed.evaluate(witness)
196			result = CheckResult{Satisfied: failure == 0, Hash: artifact.Hash, FirstFailure: failure}
197			return nil
198		})
199		return result, err
200	}
201	
202	// CheckInputFile is CheckInput with the witness read from a JSON file. All
203	// gating still runs against the live store, so a missing artifact or version
204	// is reported even when the file itself is malformed.
205	func (s *Store) CheckInputFile(name string, version int, hash, path string) (CheckResult, error) {
206		if err := validateCircuitKey(name, version); err != nil {
207			return CheckResult{}, err
208		}
209		if hash == "" {
210			return CheckResult{}, invalidf("an artifact hash is required to check inputs")
211		}
212		raw, err := os.ReadFile(path)
213		if err != nil {
214			return CheckResult{}, inputFormatf("cannot read input file %q: %v", path, err)
215		}
216		var result CheckResult
217		err = s.withLockRead(func() error {
218			circuit := findCircuit(s.data.Circuits, name, version)
219			if circuit == nil {
220				return notFoundf("circuit %q version %d does not exist", name, version)
221			}
222			if !circuit.Frozen {
223				return notFrozenf("circuit %q version %d must be frozen before inputs can be checked", name, version)
224			}
225			artifact := findArtifact(s.data.Artifacts, name, version)
226			if artifact == nil {
227				return artifactMissingf("circuit %q version %d has no compiled artifact", name, version)
228			}
229			if artifact.Hash != hash {
230				return artifactMismatchf("artifact hash %q does not belong to circuit %q version %d (bound hash %q)",
231					hash, name, version, artifact.Hash)
232			}
233			if circuit.Definition == nil {
234				return corruptf("artifact for %q v%d exists but its definition is missing", name, version)
235			}
236			parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
237			if perr != nil {
238				return corruptf("stored definition for %q v%d is unreadable: %v", name, version, perr)
239			}
240			witness, werr := parseWitness(raw, parsed.public, parsed.private)
241			if werr != nil {
242				return werr
243			}
244			failure := parsed.evaluate(witness)
245			result = CheckResult{Satisfied: failure == 0, Hash: artifact.Hash, FirstFailure: failure}
246			return nil
247		})
248		return result, err
249	}
250	
251	// validateWitness applies the witness grammar and layout rules for an
252	// in-API call.
253	func validateWitness(w Witness, public, private int) error {
254		if len(w.Public) != public {
255			return inputFormatf("public input length mismatch: got %d values, version declares %d", len(w.Public), public)
256		}
257		if len(w.Private) != private {
258			return inputFormatf("private input length mismatch: got %d values, version declares %d", len(w.Private), private)
259		}
260		for i, v := range w.Public {
261			if _, err := parseBigSignedDecimal(v); err != nil {
262				return inputFormatf("public input #%d value %q is not a decimal integer: %v", i+1, v, err)
263			}
264		}
265		for i, v := range w.Private {
266			if _, err := parseBigSignedDecimal(v); err != nil {
267				return inputFormatf("private input #%d value is not a decimal integer: %v", i+1, err)
268			}
269		}
270		return nil
271	}
272	
273	// --- lookup / mapping helpers ---------------------------------------------
274	
275	func findArtifact(as []persistArtifact, name string, version int) *persistArtifact {
276		for i := range as {
277			if as[i].Name == name && as[i].Version == version {
278				return &as[i]
279			}
280		}
281		return nil
282	}
283	
284	func artifactFromPersist(a persistArtifact) Artifact {
285		return Artifact{
286			Name: a.Name, Version: a.Version,
287			Modulus: int(a.Modulus), Constraints: a.Constraints, Hash: a.Hash,
288		}
