12	func openTestStore(t *testing.T) *Store {
13		t.Helper()
14		dir := t.TempDir()
15		s, err := Open(dir)
16		if err != nil {
17			t.Fatalf("Open: %v", err)
18		}
19		t.Cleanup(func() { s.Close() })
20		return s
21	}
22	
23	func TestCreateCircuitValidation(t *testing.T) {
24		s := openTestStore(t)
25	
26		cases := []struct {
27			name string
28			c    Circuit
29			want error
30		}{
31			{"empty name", Circuit{Name: "  ", Version: 1, Constraints: 1}, ErrInvalidArgument},
32			{"zero version", Circuit{Name: "c", Version: 0, Constraints: 1}, ErrInvalidArgument},
33			{"negative version", Circuit{Name: "c", Version: -1, Constraints: 1}, ErrInvalidArgument},
34			{"zero constraints", Circuit{Name: "c", Version: 1, Constraints: 0}, ErrInvalidArgument},
35			{"negative public", Circuit{Name: "c", Version: 1, Constraints: 1, PublicInputs: -1}, ErrInvalidArgument},
36			{"negative private", Circuit{Name: "c", Version: 1, Constraints: 1, PrivateInputs: -2}, ErrInvalidArgument},
37		}
38		for _, tc := range cases {
39			t.Run(tc.name, func(t *testing.T) {
40				if _, err := s.CreateCircuit(tc.c); !errors.Is(err, tc.want) {
41					t.Fatalf("want %v, got %v", tc.want, err)
42				}
43			})
44		}
45	
46		// Zero counts rejected on update as well.
47		if _, err := s.UpdateCircuit(Circuit{Name: "c", Version: 1, Constraints: 0}); !errors.Is(err, ErrInvalidArgument) {
48			t.Fatalf("update validation: %v", err)
49		}
50		// Nothing was created despite the rejected attempts.
51		list, err := s.ListCircuits()
52		if err != nil {
53			t.Fatal(err)
54		}
55		if len(list) != 0 {
56			t.Fatalf("rejected creates left records: %+v", list)
57		}
58	}
59	
60	func TestCreateIdempotenceAndConflict(t *testing.T) {
61		s := openTestStore(t)
62		c := Circuit{Name: "transfer", Version: 3, Constraints: 2048, PublicInputs: 2, PrivateInputs: 4, Description: "d3"}
63	
64		first, err := s.CreateCircuit(c)
65		if err != nil {
66			t.Fatal(err)
67		}
68		if first.Frozen {
69			t.Fatal("new circuit must be a draft")
70		}
71		// Same name+version with the identical description returns the stored
72		// record, regardless of the other (ignored-on-existing) count arguments.
73		same := Circuit{Name: "transfer", Version: 3, Constraints: 9999, PublicInputs: 9, PrivateInputs: 9, Description: "d3"}
74		got, err := s.CreateCircuit(same)
75		if err != nil {
76			t.Fatalf("identical re-create: %v", err)
77		}
78		if got.Constraints != 2048 || got.PublicInputs != 2 || got.PrivateInputs != 4 || got.Frozen {
79			t.Fatalf("re-create altered stored record: %+v", got)
80		}
81		// Different description is a conflict and changes nothing.
82		conflict := c
83		conflict.Description = "different"
84		if _, err := s.CreateCircuit(conflict); !errors.Is(err, ErrConflict) {
85			t.Fatalf("want conflict, got %v", err)
86		}
87		got, err = s.GetCircuit("transfer", 3)
88		if err != nil {
89			t.Fatal(err)
90		}
91		if got.Description != "d3" {
92			t.Fatalf("conflicting create mutated description: %q", got.Description)
93		}
94	
95		// Multiple versions of the same name coexist.
96		v4 := Circuit{Name: "transfer", Version: 4, Constraints: 4096, Description: "d4"}
97		if _, err := s.CreateCircuit(v4); err != nil {
98			t.Fatal(err)
99		}
100		got, err = s.GetCircuit("transfer", 3)
101		if err != nil || got.Version != 3 {
102			t.Fatalf("v3 displaced by v4: %+v %v", got, err)
103		}
104	}
105	
106	func TestUpdateRequiresDraft(t *testing.T) {
107		s := openTestStore(t)
108	
109		if _, err := s.UpdateCircuit(Circuit{Name: "ghost", Version: 1, Constraints: 10}); !errors.Is(err, ErrNotFound) {
110			t.Fatalf("update missing: want not found, got %v", err)
111		}
112		if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 1, Constraints: 100, Description: "orig"}); err != nil {
113			t.Fatal(err)
114		}
115		updated, err := s.UpdateCircuit(Circuit{Name: "c", Version: 1, Constraints: 200, PublicInputs: 1, Description: "next"})
116		if err != nil {
117			t.Fatal(err)
118		}
119		if updated.Constraints != 200 || updated.PublicInputs != 1 || updated.Description != "next" || updated.Frozen {
120			t.Fatalf("bad update result: %+v", updated)
121		}
122		if _, err := s.FreezeCircuit("c", 1); err != nil {
123			t.Fatal(err)
124		}
125		if _, err := s.UpdateCircuit(Circuit{Name: "c", Version: 1, Constraints: 300, Description: "next"}); !errors.Is(err, ErrFrozen) {
126			t.Fatalf("update frozen: want frozen, got %v", err)
127		}
128		got, _ := s.GetCircuit("c", 1)
129		if got.Constraints != 200 || got.Description != "next" || !got.Frozen {
130			t.Fatalf("frozen record mutated by rejected update: %+v", got)
131		}
132		// A later version cannot replace the frozen one.
133		if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 2, Constraints: 1}); err != nil {
134			t.Fatal(err)
135		}
136		got, _ = s.GetCircuit("c", 1)
137		if got.Constraints != 200 || !got.Frozen {
138			t.Fatalf("new version displaced frozen v1: %+v", got)
139		}
140	}
141	
142	func TestFreezeIdempotentAndImmutable(t *testing.T) {
143		s := openTestStore(t)
144		if _, err := s.FreezeCircuit("nope", 1); !errors.Is(err, ErrNotFound) {
145			t.Fatalf("want not found, got %v", err)
146		}
147		if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 1, Constraints: 10, Description: "d"}); err != nil {
148			t.Fatal(err)
149		}
150		f1, err := s.FreezeCircuit("c", 1)
151		if err != nil || !f1.Frozen {
152			t.Fatalf("freeze: %+v %v", f1, err)
153		}
154		f2, err := s.FreezeCircuit("c", 1)
155		if err != nil || !f2.Frozen || f2 != f1 {
156			t.Fatalf("re-freeze not idempotent: %+v %v", f2, err)
157		}
158	}
159	
160	func TestSetupScopedToFrozenVersion(t *testing.T) {
161		s := openTestStore(t)
162		mk := func(name string, v int, frozen bool) {
163			t.Helper()
164			if _, err := s.CreateCircuit(Circuit{Name: name, Version: v, Constraints: 64, Description: fmt.Sprintf("%s%d", name, v)}); err != nil {
165				t.Fatal(err)
166			}
167			if frozen {
168				if _, err := s.FreezeCircuit(name, v); err != nil {
169					t.Fatal(err)
170				}
171			}
172		}
173	
174		if _, err := s.RecordSetup("ghost", 1); !errors.Is(err, ErrNotFound) {
175			t.Fatalf("want not found, got %v", err)
176		}
177		mk("c", 1, false)
178		if _, err := s.RecordSetup("c", 1); !errors.Is(err, ErrNotFrozen) {
179			t.Fatalf("want not frozen, got %v", err)
180		}
181		if _, err := s.FreezeCircuit("c", 1); err != nil {
182			t.Fatal(err)
183		}
184		if _, err := s.RecordSetup("c", 1); err != nil {
185			t.Fatalf("record setup: %v", err)
186		}
187		// Idempotent: repeat registration is harmless.
188		if _, err := s.RecordSetup("c", 1); err != nil {
189			t.Fatalf("repeat setup: %v", err)
190		}
191		if setup, found, err := s.GetSetup("c", 1); err != nil || !found || setup.Version != 1 {
192			t.Fatalf("get setup: %+v found=%v err=%v", setup, found, err)
193		}
194		if before := countSetups(t, s); before != 1 {
195			t.Fatalf("want 1 setup record, got %d", before)
196		}
197		// A sibling frozen version cannot borrow the setup.
198		mk("c", 2, true)
199		if _, err := s.SubmitJob(Job{ID: "jv2", Circuit: "c", Version: 2, Kind: "prove", Attempt: 1}); !errors.Is(err, ErrSetupMissing) {
200			t.Fatalf("want setup missing for v2, got %v", err)
201		}
202		if _, found, err := s.GetSetup("c", 2); err != nil || found {
203			t.Fatalf("v2 should have no setup, found=%v err=%v", found, err)
204		}
205		if _, err := s.RecordSetup("c", 2); err != nil {
206			t.Fatalf("record v2 setup: %v", err)
207		}
208		if got, err := s.SubmitJob(Job{ID: "jv2", Circuit: "c", Version: 2, Kind: "prove", Attempt: 1}); err != nil {
209			t.Fatalf("v2 job after its own setup: %v", got)
210		}
211		if countSetups(t, s) != 2 {
212			t.Fatalf("want 2 setups, got %d", countSetups(t, s))
213		}
214	}
215	
216	func countSetups(t *testing.T, s *Store) int {
217		t.Helper()
218		// No exported setup-list API; count through repeated job eligibility is
219		// indirect, so inspect the committed envelope directly.
220		s.mu.Lock()
221		defer s.mu.Unlock()
222		if err := lockShared(s.lock); err != nil {
223			t.Fatal(err)
224		}
225		defer unlockLock(s.lock)
226		if err := s.loadLocked(); err != nil {
227			t.Fatal(err)
228		}
229		return len(s.data.Setups)
230	}
231	
232	func readyCircuit(t *testing.T, s *Store, name string, v int) {
233		t.Helper()
234		if _, err := s.CreateCircuit(Circuit{Name: name, Version: v, Constraints: 128, Description: name}); err != nil {
235			t.Fatal(err)
236		}
237		if _, err := s.FreezeCircuit(name, v); err != nil {
238			t.Fatal(err)
239		}
240		if _, err := s.RecordSetup(name, v); err != nil {
241			t.Fatal(err)
242		}
243	}
244	
245	func TestSubmitJobFailuresAreDistinguishableAndLeaveNoTrace(t *testing.T) {
246		s := openTestStore(t)
247		if _, err := s.CreateCircuit(Circuit{Name: "draft", Version: 1, Constraints: 1}); err != nil {
248			t.Fatal(err)
249		}
250		if _, err := s.CreateCircuit(Circuit{Name: "frozen", Version: 1, Constraints: 1}); err != nil {
251			t.Fatal(err)
252		}
253		if _, err := s.FreezeCircuit("frozen", 1); err != nil {
254			t.Fatal(err)
255		}
256		readyCircuit(t, s, "ready", 1)
257	
258		cases := []struct {
259			name string
260			job  Job
261			want error
262		}{
263			{"blank id", Job{ID: "   ", Circuit: "ready", Version: 1, Kind: "prove", Attempt: 1}, ErrInvalidArgument},
264			{"blank circuit", Job{ID: "j", Circuit: "  ", Version: 1, Kind: "prove", Attempt: 1}, ErrInvalidArgument},
265			{"zero version", Job{ID: "j", Circuit: "ready", Version: 0, Kind: "prove", Attempt: 1}, ErrInvalidArgument},
266			{"zero attempt", Job{ID: "j", Circuit: "ready", Version: 1, Kind: "prove", Attempt: 0}, ErrInvalidArgument},
