		t.Fatal(err)
	}
	s.FreezeCircuit("c", 3)
	a3, _ := s.CompileCircuit("c", 3)
	res, err = s.CheckInput("c", 3, a3.Hash, Witness{Public: []string{"2"}, Private: []string{"3"}})
	if err != nil || res.Satisfied || res.FirstFailure != 2 {
		t.Fatalf("want first_failure=2, got %+v %v", res, err)
	}

